#!/usr/bin/env python3
"""NXT CAMP: inscrição Staff (R$ 30). Uso no servidor:
  python3 nxt-staff-instalar.py --verificar   # só confere, não grava nada
  python3 nxt-staff-instalar.py               # publica, com backup
Aborta sem gravar se algum trecho de produção não for o esperado."""
import base64, hashlib, os, re, shutil, sys, tempfile
from pathlib import Path
ROOT=Path('/home/novaigre/public_html')
NXT=ROOT/'next/camp-sbgp1-nov26'
OLD_JS_SHA='82db4a5a330378522acb8800d35c92e88f672ba1de5a5de73a72a81aaa623ace'
NEW_JS=base64.b64decode('')
CSS_ADD=base64.b64decode('')
WEBP=base64.b64decode('')
HTML_PAIRS=(('href="assets/inscricao.css?v=20261112.1"', 'href="assets/inscricao.css?v=20261113.1"'), ('src="assets/inscricao.js?v=20261112.1"', 'src="assets/inscricao.js?v=20261113.1"'), ('        <legend>Faça sua inscrição</legend>\n', '        <legend>Faça sua inscrição</legend>\n        <div class="nib-tipo" role="radiogroup" aria-labelledby="tipo-titulo" hidden>\n          <p class="nib-tipo-titulo" id="tipo-titulo">Tipo de inscrição</p>\n          <label class="nib-tipo-opcao"><input type="radio" name="registration_type" value="participante" checked><span><strong>Participante</strong>Adolescente de 12 a 17 anos · R$ 80,00</span></label>\n          <label class="nib-tipo-opcao"><input type="radio" name="registration_type" value="staff"><span><strong>Staff</strong>Voluntário da equipe · R$ 30,00</span></label>\n        </div>\n'))
API_PAIRS=(
 ("    $payer=clean_text($_POST['payer']??'',120);\n",
  "    $payer=clean_text($_POST['payer']??'',120);\n"
  "    // Staff: equipe de voluntários, sem responsável legal e com valor de R$ 30.\n"
  "    $isStaff=(($_POST['registration_type']??'')==='staff');\n"
  "    if($isStaff){$guardian='';$guardianPhone='';$relationship='';$birth='';$age='';$health='';}\n"
  "    if($isStaff&&strlen($phone)<10)respond(422,['ok'=>false,'message'=>'Informe seu WhatsApp com DDD.']);\n"),
 ("if($name===''||$guardian===''||$guardianPhone===''||$relationship===''||$birth===''){",
  "if($name===''||(!$isStaff&&($birth===''||$guardian===''||$guardianPhone===''||$relationship===''))){"),
 ("if($age<12||$age>17)respond(", "if(!$isStaff&&($age<12||$age>17))respond("),
 ("if(strlen($guardianPhone)<10)respond(", "if(!$isStaff&&strlen($guardianPhone)<10)respond("),
)
# Validação do nascimento só para participante. Uma das duas versões conhecidas da API.
BIRTH_VARIANTS=(
 ("    if(!preg_match('/^\\d{4}-\\d{2}-\\d{2}$/D',$birth))respond(",
  "    if(!$isStaff&&!preg_match('/^\\d{4}-\\d{2}-\\d{2}$/D',$birth))respond("),
 ("    if(!preg_match('/^(\\d{4})-(\\d{2})-(\\d{2})$/D',$birth,$parts)",
  "    if(!$isStaff){\n    if(!preg_match('/^(\\d{4})-(\\d{2})-(\\d{2})$/D',$birth,$parts)"),
)
BIRTH_V2_END=("    $age=$born->diff($today)->y;\n","    $age=$born->diff($today)->y;\n    }\n")
API_AMOUNT=re.compile(r"'amount'=>80(?:\.0+)?,")
API_AMOUNT_NEW="'amount'=>$isStaff?30.00:80.00,\n        'registration_type'=>$isStaff?'staff':'participante',"
PANEL_PAIRS=(
 (":'Pendente')?></span><h2><?=h($r['name']??'')?></h2>",
  ":'Pendente')?></span><h2><?=h($r['name']??'')?></h2><?php if(($r['registration_type']??'')==='staff'):?><span class=\"tag\" style=\"background:#ff7f40;color:#041e42\">Staff</span><?php endif;?>"),
 ("'payer_name','cell','class','address']", "'payer_name','cell','class','address','registration_type']"),
 ("'Pagador','Valor','Data','Conferido']", "'Pagador','Valor','Tipo','Data','Conferido']"),
 ("$r['amount']??$ev['amount'],$r['created_at']??''",
  "$r['amount']??$ev['amount'],(['staff'=>'Staff','participante'=>'Participante'][$r['registration_type']??'']??''),$r['created_at']??''"),
)
def sha(b): return hashlib.sha256(b).hexdigest()
def pairs(s,ps,nome):
    for a,b in ps:
        n=s.count(a)
        if n!=1: sys.exit(f'ABORTADO: {nome}: trecho encontrado {n} vez(es): {a[:70]!r}')
        s=s.replace(a,b,1)
    return s
def plan():
    files={}
    html=NXT/'inscricao.html'; js=NXT/'assets/inscricao.js'; css=NXT/'assets/inscricao.css'
    api=NXT/'api-inscricao.php'; panel=ROOT/'inscricoes/index.php'
    for p in (html,js,css,api,panel):
        if not p.is_file() or p.is_symlink(): sys.exit(f'ABORTADO: arquivo ausente: {p}')
    t=html.read_text('utf-8')
    if 'registration_type' in t: sys.exit('ABORTADO: o formulário já tem a opção Staff')
    files[html]=pairs(t,HTML_PAIRS,'inscricao.html').encode()
    o=js.read_bytes()
    if sha(o)!=OLD_JS_SHA: sys.exit(f'ABORTADO: inscricao.js de produção mudou (sha {sha(o)})')
    files[js]=NEW_JS
    c=css.read_bytes()
    if b'Staff: escolha do tipo' in c: sys.exit('ABORTADO: CSS já aplicado')
    files[css]=c+CSS_ADD
    a=api.read_text('utf-8')
    if 'isStaff' in a: sys.exit('ABORTADO: API já aplicada')
    a=pairs(a,API_PAIRS,'api-inscricao.php')
    hits=[v for v in BIRTH_VARIANTS if a.count(v[0])==1]
    if len(hits)!=1: sys.exit('ABORTADO: api-inscricao.php: validação do nascimento não reconhecida')
    a=a.replace(hits[0][0],hits[0][1],1)
    if hits[0] is BIRTH_VARIANTS[1]:
        if a.count(BIRTH_V2_END[0])!=1: sys.exit('ABORTADO: api-inscricao.php: cálculo da idade não reconhecido')
        a=a.replace(BIRTH_V2_END[0],BIRTH_V2_END[1],1)
    if len(API_AMOUNT.findall(a))!=1: sys.exit("ABORTADO: api-inscricao.php: valor 'amount'=>80 não encontrado uma vez")
    files[api]=API_AMOUNT.sub(API_AMOUNT_NEW,a).encode()
    files[panel]=pairs(panel.read_text('utf-8'),PANEL_PAIRS,'inscricoes/index.php').encode()
    files[NXT/'img/pix-nxt-camp-staff-30.webp']=WEBP
    return files
def write(p,data):
    fd,tmp=tempfile.mkstemp(prefix='.nib-staff-',dir=p.parent)
    try:
        with os.fdopen(fd,'wb') as f: f.write(data)
        if p.exists(): shutil.copymode(p,tmp)
        else: os.chmod(tmp,0o644)
        os.replace(tmp,p)
    finally:
        if os.path.exists(tmp): os.unlink(tmp)
if __name__=='__main__':
    files=plan()
    if '--verificar' in sys.argv:
        for p,d in files.items(): print('OK', p, sha(d))
        print('VERIFICADO: nada foi gravado'); sys.exit(0)
    backup=Path(tempfile.mkdtemp(prefix='nib-nxt-staff-',dir='/home/novaigre/nib-manutencao'))
    for p in files:
        if p.exists():
            dest=backup/p.relative_to(ROOT); dest.parent.mkdir(parents=True,exist_ok=True)
            shutil.copy2(p,dest); assert dest.read_bytes()==p.read_bytes()
    for p,d in files.items():
        write(p,d); assert p.read_bytes()==d; print('PUBLICADO', p, sha(d))
    print('BACKUP:', backup)
